import json, os, sys
# Writes test/targets.json (repo root relative to this file). Run calc_examples.py first.
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "test", "targets.json")
r = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "calc_out.json")))
KP01 = "KP-01 2013 (Ditjen SDA, Kriteria Perencanaan Bagian Jaringan Irigasi)"
KP02 = "KP-02 2013 (Ditjen SDA, Kriteria Perencanaan Bangunan Utama)"
T = []
def t(i, e, inp, exp, tol, src): T.append({"id": i, "engine": e, "inputs": inp, "expect": round(exp, 4), "tol": tol, "source": src})
t("E1-01-coef-month", "E1", {"A_km2": 4320, "P_mm": 300, "C": 0.5, "days": 30, "out": "Q_m3s"}, r["e1_coef_month_Q"], 0.5, "[C] Q = C*P*A/t, r13 hand calc")
t("E1-02-rational", "E1", {"C": 0.6, "I_mm_h": 20, "A_km2": 100, "out": "Qp_m3s"}, r["e1_rational_Q"], 0.5, "[C] rational Q = 0.278 C I A (KP-01 Lampiran I uses the rational form); r13")
t("E1-03-mock-wet-runoff", "E1", {"P_mm": 300, "rain_days": 15, "Ep_mm": 120, "m": 0.30, "SMC_mm": 200, "SM0_mm": 200, "i": 0.4, "k": 0.6, "V0_mm": 100, "PF": 0, "out": "runoff_mm"}, r["e1_mock"]["RO"], 0.1, "[C] F.J. Mock steps as in Rasyid & Afdhaliah ITB IGSC 2022; r13 recomputed")
t("E1-04-mock-wet-Q", "E1", {"same_as": "E1-03-mock-wet-runoff", "A_km2": 4320, "days": 30, "out": "Q_m3s"}, r["e1_mock_Q"], 0.5, "[C] r13")
t("E1-05-mock-dry-baseflow", "E1", {"P_mm": 60, "rain_days": 5, "Ep_mm": 135, "m": 0.30, "SMC_mm": 200, "SM0_mm": 200, "i": 0.4, "k": 0.6, "V0_mm": 119.328, "out": "runoff_mm (all baseflow)"}, r["e1_mock_dry"]["RO"], 0.1, "[C] r13; soil drawn to 151.3 mm, no surplus")
t("E1-06-mock-groundwater", "E1", {"same_as": "E1-03-mock-wet-runoff", "out": "V1_mm"}, r["e1_mock"]["V"], 0.05, "[C] Vn = k*Vn-1 + 0.5(1+k)*I")
t("E1-07-nreca-total", "E1", {"P_mm": 300, "PET_mm": 120, "Ra_mm_yr": 2800, "W0_mm": 600, "PSUB": 0.5, "GWF": 0.5, "GW0_mm": 100, "out": "runoff_mm"}, r["e1_nreca"]["total"], 0.2, "[C] NRECA (Crawford & Thurin 1981 structure; Nominal = 100+0.2Ra), excess-moisture ratio 0.5(1+tanh((Wi-1)/0.52)) [A, check against the NRECA chart]")
t("E1-08-nreca-storage", "E1", {"same_as": "E1-07-nreca-total", "out": "W1_mm"}, r["e1_nreca"]["W1"], 0.2, "[C] r13")
t("E1-09-bucket-day1", "E1", {"Smax_mm": 150, "S0_mm": 120, "P_mm": 100, "K_days": 2, "A_km2": 4320, "out": "Q_day1_m3s"}, r["e1_bucket_Q1"], 2, "[C] overflow 70 mm into linear reservoir, q = 70(1-e^-0.5) mm/day; r13")
t("E1-10-q80-weibull", "E1", {"flows_m3s": [420, 380, 350, 300, 280, 260, 240, 210, 190, 150], "method": "Weibull m/(n+1), linear interpolation", "out": "Q80_m3s"}, r["q80_weibull"], 0.01, "[C] KP-01 4.2.5 (80% exceedance); synthetic series")
t("E1-11-q80-normal", "E1", {"flows_m3s": [420, 380, 350, 300, 280, 260, 240, 210, 190, 150], "method": "normal: mean + z(0.2)*sd", "out": "Q80_m3s"}, r["q80_normal"], 0.1, "[C] KP-01 Tabel 4-4 row 1a (normal distribution)")
t("E2-01-grid-volume", "E2", {"dem": [[10, 11, 12], [9, 10, 11], [8, 9, 13]], "cell_m": 30, "level_m": 10.5, "out": "volume_m3"}, r["grid_vol"], 0.01, "[C] V(h) = sum cell_area*max(0,h-z); r13")
t("E2-02-grid-area", "E2", {"same_as": "E2-01-grid-volume", "out": "area_m2"}, r["grid_area"], 0.01, "[C] r13")
t("E2-03-pool-equilibrium", "E2", {"I_m3s": 500, "C": 2.2, "b_m": 100, "out": "head_m at O = I"}, r["pool_equilibrium_H"], 0.001, "[C] O = C b H^1.5 solved for O = I")
t("E2-04-pool-euler-step", "E2", {"A_m2": 2e6, "H0_m": 1.0, "I_m3s": 500, "C": 2.2, "b_m": 100, "dt_s": 3600, "out": "H1_m"}, r["pool_step_H1"], 0.001, "[C] explicit step H1 = H0 + (I-O)dt/A")
t("E2-05-puls-linear", "E2", {"A_m2": 2e6, "H1_m": 1.0, "I1": 500, "I2": 500, "O_per_m": 100, "dt_s": 3600, "out": "H2_m"}, r["puls_linear_H2"], 0.0005, "[C] level-pool (Puls) trapezoid step, closed form for linear outflow")
t("E2-06-evap-loss", "E2", {"pan_mm_d": 4.6, "pan_coef": 0.7, "area_km2": 1, "out": "loss_m3_per_day"}, r["evap_loss_m3d_1km2"], 1, "[S] pan 4.6 mm/d Belitang, JICA 1982 Upper Komering Pre-FS Annex I 1.8; [A] pan coefficient 0.7")
t("E3-01-gate-free-kp02", "E3", {"mu": 0.60, "a_m": 1.0, "b_m": 10, "h1_m": 5.0, "K": 1.0, "g": 9.81, "out": "Q_m3s"}, r["gate_free"], 0.05, KP02 + " eq 4-42; mu [R] from Gambar 4-40")
t("E3-02-gate-free-energy", "E3", {"Cc": 0.61, "a_m": 1.0, "b_m": 10, "h1_m": 5.0, "out": "Q_m3s"}, r["gate_energy"], 0.05, "[C] energy + contraction form, Cc = 0.61 (standard texts)")
t("E3-03-intake-submerged", "E3", {"mu": 0.80, "b_m": 3.0, "a_m": 1.5, "z_m": 0.20, "out": "Q_m3s"}, r["intake_submerged"], 0.01, KP02 + " eq 5-3, mu = 0.80")
t("E3-04-crest", "E3", {"Cd": 1.30, "b_m": 100, "H1_m": 3.0, "out": "Q_m3s"}, r["crest_Q"], 0.5, KP02 + " eq 4-2 (Cd = C0 C1 C2, C0 max 1.49)")
t("E3-05-effective-width", "E3", {"B_m": 100, "n_piers": 4, "Kp": 0.01, "Ka": 0.10, "H1_m": 3.0, "out": "Be_m"}, r["be"], 0.001, KP02 + " eq 4-1, Tabel 4-1")
t("E3-06-crest-with-be", "E3", {"Cd": 1.30, "B_m": 100, "n_piers": 4, "Kp": 0.01, "Ka": 0.10, "H1_m": 3.0, "out": "Q_m3s"}, r["crest_Q_be"], 0.5, KP02 + " eq 4-1 + 4-2")
t("E3-07-manning", "E3", {"b_m": 80, "side_z": 2, "y_m": 4, "n": 0.035, "S": 0.0003, "out": "Q_m3s"}, r["manning_Q"], 0.5, "[C] Manning Q = (1/n) A R^(2/3) S^(1/2), trapezoid")
t("E4-01-d8-acc", "E4", {"dem": "toy 5x5 valley in calc_examples.py", "cell_m": 30, "out": "outlet catchment m2"}, r["d8_area_outlet_m2"], 0.01, "[C] D8 steepest descent, diagonals /sqrt2")
t("E4-02-fill-cells", "E4", {"dem": "toy 5x5, rows 0-2 behind dam line", "crest_m": 6, "seed": [2, 2], "out": "flooded cells"}, r["fill_cells"], 0, "[C] 4-connected flood fill below crest")
t("E4-03-fill-volume", "E4", {"same_as": "E4-02-fill-cells", "out": "volume_m3"}, r["fill_vol_m3"], 0.01, "[C] r13")
t("E4-04-hand", "E4", {"dem": "toy 5x5", "drain_threshold_cells": 3, "cell": [0, 0], "out": "HAND_m"}, r["hand_cell_0_0"], 0.001, "[C] HAND = z - z(first drainage cell along D8)")
t("E4-05-hand-extent", "E4", {"dem": "toy 5x5", "drain_threshold_cells": 3, "stage_m": 2.0, "out": "cells with HAND <= stage"}, r["hand_flooded_at_stage2"], 0, "[C] r13")
t("E6-01-lp-table", "E6", {"M_mm_d": 5.0, "T_d": 30, "S_mm": 250, "out": "IR_mm_d"}, r["lp_M5_T30_S250"], 0.05, KP01 + " Tabel A.2.1 gives 11,1")
t("E6-02-lp-table-b", "E6", {"M_mm_d": 11.0, "T_d": 45, "S_mm": 300, "out": "IR_mm_d"}, r["lp_M11_T45_S300"], 0.05, KP01 + " Tabel A.2.1 gives 13,6")
t("E6-03-re", "E6", {"R5_halfmonth_mm": 90, "out": "Re_mm_d"}, r["re"], 0.001, KP01 + " eq A.2.5 Re = 0.7 R5/15")
t("E6-04-nfr", "E6", {"ETo": 4.0, "Kc": 1.10, "P": 2.0, "WLR": 3.3, "Re": 4.2, "out": "NFR_mm_d"}, r["nfr"], 0.001, KP01 + " Lampiran II")
t("E6-05-dr", "E6", {"NFR_mm_d": 5.5, "eff": 0.65, "out": "DR_l_s_ha"}, r["dr_lpsha"], 0.002, KP01 + " Tabel A.2.x note 4: DR = NFR/(8.64*0.65); KP-01 prints 0,97 for 5,5")
t("E6-06-golongan", "E6", {"groups": 3, "stagger_days": 15, "ETo": 4.0, "P": 2.0, "R5": 90, "out": "mean NFR mm/d (LP, Kc1.10, Kc1.05)"}, r["golongan_avg_nfr"], 0.01, "[C] r13, KP-01 A.2.3.3 sums groups")
t("FF-01-gumbel-100", "E4", {"annual_max_m3s": [820, 950, 1100, 760, 1300, 1020, 880, 1450, 990, 1180], "Yn": 0.4952, "Sn": 0.9496, "T": 100, "out": "Q_m3s"}, r["gumbel_Q100"], 1, "[C] Gumbel with Yn/Sn for n = 10 (table as in Soewarno/SNI 2415-type practice); synthetic data")
t("FF-02-gumbel-chow-100", "E4", {"same_as": "FF-01-gumbel-100", "K": "Chow -(sqrt6/pi)(0.5772+ln ln(T/(T-1)))", "out": "Q_m3s"}, r["gumbel_chow_Q100"], 1, "[C] r13")
t("FF-03-lp3-100", "E4", {"same_as": "FF-01-gumbel-100", "log": 10, "KT": "Wilson-Hilferty", "out": "Q_m3s"}, r["lp3_Q100"], 5, "[C] r13; Cs = 0.262; table KT differs from Wilson-Hilferty by < 0.01 for |Cs| < 1")
t("FF-04-kt-cs05", "E4", {"Cs": 0.5, "T": 100, "out": "KT"}, r["KT_cs05_T100"], 0.005, "[C] Wilson-Hilferty; standard LP3 table gives 2.686")
json.dump(T, open(OUT, "w"), indent=1)
print(len(T))
